import itertools


def all_arrangements(items):
    return list(itertools.permutations(items))


def combo_with_replacement(items, r):
    return list(itertools.combinations_with_replacement(items, r))


def power_set(items):
    result = []
    for size in range(len(items) + 1):
        result.extend(itertools.combinations(items, size))
    return result
